function escapeHtml(s) {
	return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function escapeRegExp(s) {
	return String(s == null ? '' : s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
function bundledResponse(path, status, contentType, noStore) {
	const body = BUNDLED_PAGES[path];
	if (body == null) return new Response('Not Found', { status: 404 });
	const headers = { 'Content-Type': contentType || 'text/html;charset=UTF-8' };
	if (noStore) { headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, proxy-revalidate'; headers['Pragma'] = 'no-cache'; headers['Expires'] = '0'; }
	return new Response(body, { status: status || 200, headers });
}
